type Scope='learner'|'school'|'university';
type RecordItem={kind:string;key:string;value:any};
type Action={title:string;description?:string;kind?:string;key?:string;fields?:{name:string;label:string;type?:string;options?:string[];value?:string;required?:boolean}[];content?:ReactNode;submit?:string};
type Context={scope:Scope;records:RecordItem[];save:(kind:string,key:string,value:any)=>Promise<boolean>;get:(kind:string,key:string)=>any;open:(action:Action)=>void;message:(text:string)=>void};
const PortalContext=createContext<Context>(null!);
const usePortal=()=>useContext(PortalContext);
